		Service service = new Service(Var.of("input"),
				new StatementPattern(Var.of("subject"), Var.of("remotePredicate", iri("urn:remote")), Var.of("remote")),
				"SERVICE ?input { ?subject <urn:remote> ?remote }", Map.of(), null, false);
